python
def binary_search(arr: list, target: int) -> int:
    # 闭区间 [left, right]，right 必须指向最后一个有效下标，
    # 否则 left == right == len(arr) 时 arr[mid] 会越界（IndexError）。
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1
